function escapeHtml(text) {
    return text
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
}


function containsTerm(text, term) {
    const pattern = "(^|[^\\p{L}\\p{N}_])" +
        escapeRegExp(term) +
        "(?=$|[^\\p{L}\\p{N}_])";
    return new RegExp(pattern, "iu").test(text);
}

function escapeRegExp(text) {
    return text.replace(
        /[.*+?^${}()|[\]\\]/g,
        "\\$&"
    );
}

/* QUICK REWRITE ACTION HANDLERS */
const quickCalmButton = document.getElementById("quick-calm");
const quickProfessionalButton = document.getElementById("quick-professional");
const quickFriendlyButton = document.getElementById("quick-friendly");
const quickShortenButton = document.getElementById("quick-shorten");

if (quickCalmButton) {
    quickCalmButton.addEventListener("click", () => {
        rewriteMode.value = "balanced";
        toneGoal.value = "deescalate";
        if (messageInput.value.trim()) window.kenesafeRequestRewrite?.({ immediate: true }); });
}

if (quickProfessionalButton) {
    quickProfessionalButton.addEventListener("click", () => {
        rewriteMode.value = "formal";
        toneGoal.value = "professional";
        if (messageInput.value.trim()) window.kenesafeRequestRewrite?.({ immediate: true }); });
}

if (quickFriendlyButton) {
    quickFriendlyButton.addEventListener("click", () => {
        rewriteMode.value = "casual";
        toneGoal.value = "deescalate";
        if (messageInput.value.trim()) window.kenesafeRequestRewrite?.({ immediate: true }); });
}

if (quickShortenButton) {
    quickShortenButton.addEventListener("click", () => {
        if (!messageInput.value.trim()) {
            messageInput.focus();
            analyzeMessage(messageInput.value);
            return;
        }
        window.kenesafeRewriteInstruction =
            "Shorten the message substantially while preserving its key meaning, facts, request, and boundaries. Keep it respectful and natural. Do not add unsupported information.";
        window.kenesafeRequestRewrite?.({ immediate: true });
    });
}
/* KEYBOARD SHORTCUT HANDLERS */
document.addEventListener("keydown", (event) => {
    if (!event.ctrlKey || event.altKey || event.metaKey) {
        return;
    }

    const key = event.key.toLowerCase();
    const activeElement = document.activeElement;
    const isCaptionDescription =
        activeElement && activeElement.id === "caption-description";

    if (event.key === "Enter" && !event.shiftKey && !isCaptionDescription) {
        event.preventDefault();
        window.kenesafeRequestRewrite?.({ immediate: true });
        return;
    }

    if (!event.shiftKey) {
        return;
    }

    if (key === "y") {
        event.preventDefault();
        copyButton.click();
    } else if (key === "f") {
        event.preventDefault();
        rewriteMode.value = "formal";
        window.kenesafeRequestRewrite?.({ immediate: true });
    } else if (key === "l") {
        event.preventDefault();
        rewriteMode.value = "casual";
        window.kenesafeRequestRewrite?.({ immediate: true });
    }
});
messageInput.addEventListener("input", () => {
    if (!messageInput.value.trim()) {
        toneLabel.textContent = currentLanguage === "sw" ? "Hakuna ujumbe uliochanganuliwa" : "No message analyzed";
    }

    updateMessageCount(messageInput.value);
    analyzeMessage(messageInput.value);

    if (messageInput.value.trim()) {
        window.kenesafeRequestRewrite?.();
    } else {
        window.clearTimeout(window.kenesafeCourtesyRewriteTimer);
        rewriteBox.textContent = "";
        if (rewriteReadyCard) rewriteReadyCard.hidden = true;
        setStatus(document.getElementById("ai-status"), "", "");
    }
});

toneGoal.addEventListener("change", () => {
    if (messageInput.value.trim()) window.kenesafeRequestRewrite?.();
});

incidentPreset.addEventListener("change", () => {
    if (messageInput.value.trim()) window.kenesafeRequestRewrite?.();
});

rewriteMode.addEventListener("change", () => {
    if (messageInput.value.trim()) window.kenesafeRequestRewrite?.();
});

courtesySlider.addEventListener("input", () => {
    if (!messageInput.value.trim()) {
        toneLabel.textContent = currentLanguage === "sw" ? "Hakuna ujumbe uliochanganuliwa" : "No message analyzed";
    }

    updateMessageCount(messageInput.value);

courtesyValue.textContent =
        courtesySlider.value + "%";

    
clearTimeout(window.kenesafeCourtesyRewriteTimer); if (messageInput.value.trim()) { window.kenesafeCourtesyRewriteTimer = setTimeout(() => window.kenesafeRequestRewrite?.(), 700); }
    
});

copyButton.addEventListener("click", async () => {
    const text = rewriteBox.textContent.trim();
    const placeholder = currentLanguage === "sw"
        ? "Ujumbe wako ulioboreshwa utaonekana hapa."
        : "Your polished message will appear here.";

    if (!text || text === placeholder) return;

    let copied = false;

    try {
        if (navigator.clipboard && window.isSecureContext) {
            await navigator.clipboard.writeText(text);
            copied = true;
        }
    } catch (error) {
        copied = false;
    }

    if (!copied) {
        const temporaryTextarea = document.createElement("textarea");
        temporaryTextarea.value = text;
        temporaryTextarea.setAttribute("readonly", "");
        temporaryTextarea.style.position = "fixed";
        temporaryTextarea.style.left = "-9999px";
        document.body.appendChild(temporaryTextarea);
        temporaryTextarea.select();

        try {
            copied = document.execCommand("copy");
        } catch (error) {
            copied = false;
        } finally {
            temporaryTextarea.remove();
        }
    }

    if (copied) {
        const originalLabel = currentLanguage === "sw"
            ? "Nakili ujumbe ulioboreshwa"
            : "Copy polished message";

        copyButton.textContent = currentLanguage === "sw"
            ? "Imenakiliwa!"
            : "Copied!";

        setTimeout(() => {
            copyButton.textContent = originalLabel;
        }, 1500);
    } else {
        alert(currentLanguage === "sw"
            ? "Kunakili kumeshindwa. Tafadhali chagua maandishi na uyakili mwenyewe."
            : "Copy failed. Please select and copy the text manually.");
    }
});
updateMessageCount(messageInput.value);

courtesyValue.textContent =
    courtesySlider.value + "%";










function updateScoreExplanation(text, intensity) {
    const reasons = [];
    const lower = text.toLowerCase();

    const aggressiveFound = aggressiveWords.filter(word =>
        containsTerm(lower, word)
    );

    const confrontationalFound =
        confrontationalPhrases.filter(phrase =>
            containsTerm(lower, phrase)
        );
    const blameFound = blamePhrases.filter(phrase =>
        containsTerm(lower, phrase)
    );
    const dismissiveFound = dismissivePhrases.filter(phrase =>
        containsTerm(lower, phrase)
    );
    const benignFindToTalkContext = /\bnitakutafuta\b.{0,40}\b(tuongee|tuzungumze|tukiongee)\b/iu.test(lower);
    const pressureFound = pressurePhrases.filter(phrase =>
        containsTerm(lower, phrase) &&
        !(benignFindToTalkContext && phrase === "nitakutafuta")
    );
    const animalFound = animalInsultPhrases.filter(phrase =>
        containsTerm(lower, phrase)
    );
    const threatFound = threatPhrases.filter(phrase =>
        containsTerm(lower, phrase) &&
        !(benignFindToTalkContext && phrase === "nitakutafuta")
    );

    if (threatFound.length > 0) {
        reasons.push({
            type: "high",
            text: currentLanguage === "sw"
                ? `Kauli zinazoweza kusikika kama vitisho: ${threatFound.join(", ")}`
                : `Potentially threatening wording: ${threatFound.join(", ")}`
        });
    }

    if (animalFound.length > 0) {
        reasons.push({
            type: "high",
            text: currentLanguage === "sw"
                ? `Matusi ya kumlinganisha mtu na mnyama: ${animalFound.join(", ")}`
                : `Animal-based name-calling: ${animalFound.join(", ")}`
        });
    }

    if (blameFound.length > 0) {
        reasons.push({
            type: "medium",
            text: currentLanguage === "sw"
                ? `Lugha ya kulaumu imegunduliwa: ${blameFound.join(", ")}`
                : `Blaming language detected: ${blameFound.join(", ")}`
        });
    }

    if (dismissiveFound.length > 0) {
        reasons.push({
            type: "medium",
            text: currentLanguage === "sw"
                ? `Lugha ya kupuuza imegunduliwa: ${dismissiveFound.join(", ")}`
                : `Dismissive wording detected: ${dismissiveFound.join(", ")}`
        });
    }

    if (pressureFound.length > 0) {
        reasons.push({
            type: "medium",
            text: currentLanguage === "sw"
                ? `Lugha ya kuweka shinikizo imegunduliwa: ${pressureFound.join(", ")}`
                : `Pressuring language detected: ${pressureFound.join(", ")}`
        });
    }

    if (confrontationalFound.length > 0) {
        reasons.push({
            type: "medium",
            text: currentLanguage === "sw" ? `Lugha ya makabiliano imegunduliwa: ${confrontationalFound.length} ${confrontationalFound.length === 1 ? "kauli" : "kauli"}` : `Confrontational language detected: ${confrontationalFound.length} phrase${confrontationalFound.length === 1 ? "" : "s"}`
        });
    }
    const intensifierFound = intensifiers.filter(word =>
        containsTerm(lower, word)
    );

    const capsWords = text
        .split(/\s+/)
        .filter(word => {
            const letters = word.replace(/[^A-Za-z]/g, "");
            return letters.length >= 2 &&
                letters === letters.toUpperCase();
        });

    const exclamationCount = (text.match(/!/g) || []).length;
    const questionCount = (text.match(/\?/g) || []).length;

    aggressiveFound.forEach(word => {
        reasons.push({
            type: "high",
            text: currentLanguage === "sw" ? `Lugha kali: "${word}"` : `Aggressive language: "${word}"`
        });
    });

    if (intensifierFound.length > 0) {
        reasons.push({
            type: "medium",
            text: currentLanguage === "sw" ? `Maneno yanayoongeza ukali: ${intensifierFound.join(", ")}` : `Intensifying language: ${intensifierFound.join(", ")}`
        });
    }

    if (capsWords.length > 0) {
        reasons.push({
            type: "medium",
            text: currentLanguage === "sw" ? "HERUFI KUBWA ZOTE zinaweza kuongeza ukali unaotambuliwa" : "ALL CAPS can increase perceived intensity"
        });
    }

    if (exclamationCount >= 2) {
        reasons.push({
            type: "medium",
            text: currentLanguage === "sw" ? `Alama za mshangao zilizorudiwa zimegunduliwa (${exclamationCount})` : `Repeated exclamation marks detected (${exclamationCount})`
        });
    }

    if (questionCount >= 2) {
        reasons.push({
            type: "medium",
            text: currentLanguage === "sw" ? `Alama za kuuliza zilizorudiwa zimegunduliwa (${questionCount})` : `Repeated question marks detected (${questionCount})`
        });
    }

    if (reasons.length === 0) {
        reasons.push({
            type: "low",
            text: currentLanguage === "sw" ? "Hakuna viashiria vikubwa vya ukali vilivyogunduliwa" : "No strong intensity signals detected"
        });
    }

    const container = document.getElementById("score-reasons");

    container.innerHTML = reasons.map(reason => `
        <div class="score-reason ${reason.type}">
            <span class="reason-dot"></span>
            <span>${escapeHtml(reason.text)}</span>
        </div>
    `).join("");
}




































